// Données de démonstration : aucune connexion extérieure.
const previsions = {
  lisbonne: 'Ensoleillé, 22 °C, 21 °C, 19 °C',
  cracovie: 'Nuageux, 9 °C, 7 °C, averses',
  seville: 'Ensoleillé, 26 °C, 27 °C, 25 °C',
};
const v = (query.ville || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
return previsions[v] || 'Ville inconnue du service météo.';
